class Bus {
  constructor() {
    this.handlers = new Map(); // name -> [{ fn, active }]
  }

  on(name, fn) {
    const entry = { fn, active: true };
    if (!this.handlers.has(name)) this.handlers.set(name, []);
    this.handlers.get(name).push(entry);
    return () => this.off(name, entry);
  }

  once(name, fn) {
    const off = this.on(name, (payload) => {
      off();
      return fn(payload);
    });
    return off;
  }

  off(name, entry) {
    entry.active = false;
    const list = this.handlers.get(name);
    if (!list) return;
    const i = list.indexOf(entry);
    if (i !== -1) list.splice(i, 1);
  }

  emit(name, payload) {
    const list = this.handlers.get(name);
    if (!list) return 0;
    const snapshot = [...list];
    const errors = [];
    let called = 0;
    for (const entry of snapshot) {
      if (!entry.active) continue;
      called += 1;
      try {
        entry.fn(payload);
      } catch (e) {
        errors.push(e);
      }
    }
    if (errors.length > 0) throw new AggregateError(errors, `${errors.length} handler(s) failed for ${name}`);
    return called;
  }
}

